177	.is-dom-init-box-hidden {
178	  opacity: 0;
179	  visibility: hidden;
180	  transform: translate3d(0, var(--block-reveal-offset-y), 0);
181	  filter: blur(var(--block-reveal-blur));
182	  pointer-events: none;
183	}
