185	.is-block-reveal {
186	  opacity: 0;
187	  visibility: hidden;
188	  transform: translate3d(0, var(--block-reveal-offset-y), 0);
189	  filter: blur(var(--block-reveal-blur));
190	  pointer-events: none;
191	  transition:
192	    opacity var(--transition-slow),
193	    transform var(--transition-slow),
194	    filter var(--duration-default) var(--ease-default),
195	    visibility 0s linear var(--duration-slow);
196	  will-change: transform, opacity, filter;
197	  transform-origin: 50% 100%;
198	  backface-visibility: hidden;
199	
200	  &.is-block-reveal-up {
201	    opacity: 1;
202	    visibility: visible;
203	    transform: translate3d(0, 0, 0);
204	    filter: blur(0);
205	    pointer-events: auto;
206	    transition-delay: 0s, 0s, 0s, 0s;
207	  }
208	
209	  &.is-block-reveal-down {
210	    opacity: 0;
211	    visibility: visible;
212	    transform: translate3d(0, var(--block-reveal-offset-y), 0);
213	    filter: blur(var(--block-reveal-blur));
214	    pointer-events: none;
215	    transition:
216	      opacity var(--transition-slow),
217	      transform var(--transition-slow),
218	      filter var(--duration-default) var(--ease-default),
219	      visibility 0s linear var(--duration-slow);
220	  }
221	
222	  &.is-block-reveal-hidden,
223	  &.is-block-reveal-instant {
224	    transition: none;
225	    opacity: 0;
226	    visibility: hidden;
227	    transform: translate3d(0, var(--block-reveal-offset-y), 0);
228	    filter: blur(var(--block-reveal-blur));
229	    pointer-events: none;
230	  }
231	}
