3	.no-work-modal {
4	  $root: &;
5	  position: fixed;
6	  inset: 0;
7	  z-index: var(--z-index-modal);
8	  display: flex;
9	  align-items: center;
10	  justify-content: center;
11	  padding: var(--modal-viewport-offset);
12	  pointer-events: none;
13	
14	  &__top {
15	    padding: var(--gutter-xl);
16	  }
17	
18	  &__backdrop {
19	    border: 0;
20	    cursor: pointer;
21	    z-index: 0;
22	  }
23	
24	  &__shell {
25	    position: relative;
26	    z-index: 1;
27	    width: min(100%, fluid(544, 1024));
28	  }
29	
30	  &__panel {
31	    position: relative;
32	    z-index: 1;
33	    width: 100%;
34	    background: var(--clr-surface-default);
35	    background-image:
36	      repeating-linear-gradient(
37	        to right,
38	        color-mix(in srgb, var(--clr-white-08) 50%, transparent) 0 1px,
39	        transparent 1px fluid(20, 28)
40	      ),
41	      repeating-linear-gradient(
42	        to bottom,
43	        color-mix(in srgb, var(--clr-white-08) 50%, transparent) 0 1px,
44	        transparent 1px fluid(20, 28)
45	      );
46	    border: 1px solid var(--clr-border-default);
47	
48	    opacity: 0;
49	    filter: blur(12px);
50	    max-height: 76vh;
51	    overflow-y: auto;
52	    overscroll-behavior: contain;
53	    -webkit-overflow-scrolling: touch;
54	    touch-action: pan-y;
55	    transform: translate3d(0, fluid(48, 72), 0) scale(0.985);
56	    transition:
57	      transform calc(var(--duration-default) + 0.04s) var(--modal-enter-ease),
58	      opacity calc(var(--duration-default) + 0.04s) var(--modal-enter-ease),
59	      filter calc(var(--duration-default) + 0.04s) var(--modal-enter-ease);
60	    will-change: transform, opacity, filter;
61	  }
62	
63	  &__thumbnail {
64	    width: 100%;
65	    aspect-ratio: 16/9;
66	    overflow: hidden;
67	
68	    video {
69	      width: 100%;
70	      height: 100%;
71	      object-fit: cover;
72	      display: block;
73	    }
74	  }
75	
76	  &__content-wrap {
77	    overflow: hidden;
78	    position: relative;
79	    isolation: isolate;
80	
81	    > * {
82	      position: relative;
83	      z-index: 1;
84	    }
85	  }
86	
87	  &__header {
88	    min-width: 0;
89	    display: grid;
90	    gap: var(--gutter-xs);
91	  }
92	
93	  &__title {
94	    color: var(--clr-text-title);
95	    @include font("f-heading-1");
96	    font-weight: 700;
97	  }
98	
99	  &__content {
100	    &-title {
101	      color: var(--clr-text-title);
102	      @include font("f-heading-2");
103	      font-weight: 400;
104	    }
105	
106	    &__overview {
107	      padding: var(--gutter-xl);
108	      display: flex;
109	      gap: var(--gutter-sm);
110	      flex-direction: column;
111	    }
112	
113	    &-description {
114	      color: var(--clr-text-body);
115	      @include font("f-body-3");
116	    }
117	
118	    &__image {
119	      img {
120	        width: 100%;
121	        height: 100%;
122	        object-fit: cover;
123	        display: block;
124	      }
125	    }
126	  }
127	
128	  &__award {
129	    display: inline-flex;
130	    align-items: center;
131	    gap: var(--gutter-xs);
132	    color: var(--clr-text-body);
133	    @include font("f-body-2");
134	
135	    img {
136	      width: fluid(20, 36);
137	      height: fluid(20, 36);
138	      object-fit: contain;
139	      flex-shrink: 0;
140	    }
141	
142	    span {
143	      @include font("f-body-3");
144	      font-family: var(--family-en-title);
145	    }
146	  }
147	
148	  &__close {
149	    position: absolute;
150	    top: fluid(16, 24);
151	    right: fluid(16, 24);
152	    z-index: 2;
153	    width: fluid(36, 40);
154	    height: fluid(36, 40);
155	    padding: 0;
156	    --corner-bracket-size: var(--modal-close-corner-size);
157	  }
158	
159	  &__button {
160	    min-width: fluid(152, 188);
161	  }
162	
163	  &__info {
164	    margin-top: var(--gutter-2xl);
165	    display: flex;
166	    justify-content: space-between;
167	    align-items: flex-start;
168	
169	    &-list {
170	      display: grid;
171	      gap: var(--gutter-xs);
172	    }
173	
174	    &-item {
175	      display: grid;
176	      grid-template-columns: fluid(84, 120) 1fr;
177	      gap: var(--gutter-sm);
178	      align-items: start;
179	    }
180	
181	    &-label {
182	      color: var(--clr-text-body);
183	      @include font("f-body-3");
184	      font-family: var(--family-ui);
185	      width: fluid(84, 120);
186	      flex-shrink: 0;
187	      display: block;
188	    }
189	
190	    &-sub-list {
191	      display: flex;
192	      flex-wrap: wrap;
193	      gap: fluid(6, 10);
194	    }
195	
196	    &-sub-text,
197	    &-client,
198	    &-time {
199	      color: var(--clr-text-title);
200	      @include font("f-body-1");
201	    }
202	  }
203	
204	  &.is-open {
205	    pointer-events: auto;
206	
207	    #{$root}__backdrop {
208	      opacity: 1;
209	      visibility: visible;
210	    }
211	
212	    #{$root}__panel {
213	      opacity: 1;
214	      filter: blur(0);
215	      transform: translate3d(0, 0, 0) scale(1);
216	    }
217	  }
218	
219	  &.is-closing {
220	    pointer-events: none;
221	
222	    #{$root}__panel {
223	      opacity: 0;
224	      filter: blur(10px);
225	      transform: translate3d(0, fluid(56, 84), 0) scale(0.985);
226	    }
227	
228	    #{$root}__backdrop {
229	      opacity: 0;
230	      visibility: hidden;
231	    }
232	  }
233	
234	  @media (prefers-reduced-motion: reduce) {
235	    #{$root}__backdrop,
236	    #{$root}__panel {
237	      transition: none;
238	    }
239	  }
240	
241	  @include mq(md) {
242	    &__panel {
243	      max-height: 88vh;
244	    }
245	
246	    &__info {
247	      flex-direction: column;
248	      gap: var(--gutter-md);
249	    }
250	
251	    &__button {
252	      min-width: 0;
253	      width: 100%;
254	    }
255	  }
256	
257	  @include mq(sm) {
258	    &__top {
259	      padding: var(--gutter-md);
260	    }
261	
262	    &__content {
263	      &__overview {
264	        padding: var(--gutter-md);
265	      }
266	    }
267	  }
268	}
269	

