2	import { Helpers } from "../utils/Helpers.js";
3	import { PerformanceProfile } from "../utils/PerformanceProfile.js";
4	import type {
5	  ResponsiveBreakpoint,
6	  ResponsiveEnvironmentInput,
7	  ResponsiveListener,
8	  ResponsiveSnapshot,
9	} from "../types/runtime.types.js";
10	
11	const DEFAULT_VIEWPORT_WIDTH = 1440;
12	const DEFAULT_VIEWPORT_HEIGHT = 900;
13	const DEFAULT_DEVICE_PIXEL_RATIO = 1;
14	
15	export class ResponsiveRuntime {
16	  private _snapshot: ResponsiveSnapshot | null = null;
17	  private _listeners = new Set<ResponsiveListener>();
18	  private _reduceMotionMedia: MediaQueryList | null = null;
19	  private _reduceMotionHandler: (() => void) | null = null;
20	  private _initialized = false;
21	
22	  init(): void {
23	    if (this._initialized) return;
24	    this._initialized = true;
25	    this.updateFromWindow();
26	    this._bindPreferenceListeners();
27	  }
28	
29	  dispose(): void {
30	    if (this._reduceMotionMedia && this._reduceMotionHandler) {
31	      this._reduceMotionMedia.removeEventListener(
32	        "change",
33	        this._reduceMotionHandler,
34	      );
35	    }
36	    this._reduceMotionMedia = null;
37	    this._reduceMotionHandler = null;
38	    this._listeners.clear();
39	    this._initialized = false;
40	  }
41	
42	  updateFromWindow(): Readonly<ResponsiveSnapshot> {
43	    const snapshot = this._createSnapshot();
44	    this._snapshot = snapshot;
45	    this._applyCssVariables(snapshot);
46	    this._listeners.forEach((listener) => listener(snapshot));
47	    return snapshot;
48	  }
49	
50	  getSnapshot(): Readonly<ResponsiveSnapshot> {
51	    if (!this._snapshot) {
52	      return this.updateFromWindow();
53	    }
54	    return this._snapshot;
55	  }
56	
57	  subscribe(listener: ResponsiveListener): () => void {
58	    this._listeners.add(listener);
59	    listener(this.getSnapshot());
60	    return () => {
61	      this._listeners.delete(listener);
62	    };
63	  }
64	
65	  private _createSnapshot(): ResponsiveSnapshot {
66	    const device = Device.getDefault();
67	    device.updateFromWindow();
68	    const viewportWidth = device.viewportWidth || DEFAULT_VIEWPORT_WIDTH;
69	    const viewportHeight = device.viewportHeight || DEFAULT_VIEWPORT_HEIGHT;
70	    const devicePixelRatio =
71	      typeof window === "undefined"
72	        ? DEFAULT_DEVICE_PIXEL_RATIO
73	        : Math.max(1, window.devicePixelRatio || DEFAULT_DEVICE_PIXEL_RATIO);
74	    const reducedMotion = this._prefersReducedMotion();
75	    const environment = this._createEnvironmentInput(
76	      viewportWidth,
77	      viewportHeight,
78	      devicePixelRatio,
79	      device.isMobile,
80	      reducedMotion,
81	    );
82	    const performance = PerformanceProfile.getMainProfile(environment);
83	    const pixelRatioMax = performance.enginePixelRatioMax;
84	    const breakpoint = this._resolveBreakpoint(viewportWidth);
85	
86	    return {
87	      viewportWidth,
88	      viewportHeight,
89	      deviceType: device.deviceType,
90	      isMobile: device.isMobile,
91	      breakpoint,
92	      render: {
93	        devicePixelRatio,
94	        pixelRatioMax,
95	        clampedPixelRatio: Math.min(devicePixelRatio, pixelRatioMax),
96	      },
97	      flags: {
98	        reducedMotion,
99	        hoverCapable: this._matchesMedia("(hover: hover) and (pointer: fine)"),
100	        coarsePointer: this._matchesMedia("(pointer: coarse)"),
101	      },
102	      performance,
103	      tokens: {
104	        viewportScale: this._resolveViewportScale(viewportWidth),
105	        typographyScale: this._resolveTypographyScale(viewportWidth),
106	        worldScale: this._resolveWorldScale(viewportWidth),
107	      },
108	    };
109	  }
110	
111	  private _createEnvironmentInput(
112	    viewportWidth: number,
113	    viewportHeight: number,
114	    devicePixelRatio: number,
115	    isMobile: boolean,
116	    reducedMotion: boolean,
117	  ): ResponsiveEnvironmentInput {
118	    const hardwareConcurrency =
119	      typeof navigator === "undefined"
120	        ? 8
121	        : navigator.hardwareConcurrency ?? 8;
122	    const deviceMemory = this._resolveDeviceMemory();
123	    return {
124	      viewportWidth,
125	      viewportHeight,
126	      devicePixelRatio,
127	      isMobile,
128	      reducedMotion,
129	      hardwareConcurrency,
130	      deviceMemory,
131	    };
132	  }
133	
134	  private _resolveBreakpoint(viewportWidth: number): ResponsiveBreakpoint {
135	    if (viewportWidth < 768) return "mobile";
136	    if (viewportWidth < 1024) return "tablet";
137	    if (viewportWidth < 1600) return "desktop";
138	    return "wide";
139	  }
140	
141	  private _resolveViewportScale(viewportWidth: number): number {
142	    return Helpers.clamp(viewportWidth / DEFAULT_VIEWPORT_WIDTH, 0.72, 1.24);
143	  }
144	
145	  private _resolveTypographyScale(viewportWidth: number): number {
146	    return Helpers.clamp(viewportWidth / 1600, 0.82, 1.08);
147	  }
148	
149	  private _resolveWorldScale(viewportWidth: number): number {
150	    return Helpers.clamp(viewportWidth / 1440, 0.8, 1.12);
151	  }
152	
153	  private _prefersReducedMotion(): boolean {
154	    return this._matchesMedia("(prefers-reduced-motion: reduce)");
155	  }
156	
157	  private _matchesMedia(query: string): boolean {
158	    if (typeof window === "undefined" || typeof window.matchMedia !== "function") {
159	      return false;
160	    }
161	    return window.matchMedia(query).matches;
162	  }
163	
164	  private _resolveDeviceMemory(): number | undefined {
165	    if (typeof navigator === "undefined") return undefined;
166	    const nav = navigator as Navigator & { deviceMemory?: number };
167	    return typeof nav.deviceMemory === "number" ? nav.deviceMemory : undefined;
168	  }
169	
170	  private _applyCssVariables(snapshot: ResponsiveSnapshot): void {
171	    if (typeof document === "undefined") return;
172	    const root = document.documentElement;
173	    root.style.setProperty("--rvw", String(snapshot.viewportWidth));
174	    root.style.setProperty("--rvh", String(snapshot.viewportHeight));
175	    root.style.setProperty("--rdpr", String(snapshot.render.clampedPixelRatio));
176	    root.style.setProperty("--r-breakpoint", snapshot.breakpoint);
177	    root.style.setProperty("--r-viewport-scale", String(snapshot.tokens.viewportScale));
178	    root.style.setProperty(
179	      "--r-typography-scale",
180	      String(snapshot.tokens.typographyScale),
181	    );
182	    root.style.setProperty("--r-world-scale", String(snapshot.tokens.worldScale));
183	  }
184	
185	  private _bindPreferenceListeners(): void {
186	    if (typeof window === "undefined" || typeof window.matchMedia !== "function") {
187	      return;
188	    }
189	    this._reduceMotionMedia = window.matchMedia("(prefers-reduced-motion: reduce)");
190	    this._reduceMotionHandler = () => {
191	      this.updateFromWindow();
192	    };
193	    this._reduceMotionMedia.addEventListener("change", this._reduceMotionHandler);
194	  }
195	
196	  private static _default: ResponsiveRuntime | null = null;
197	
198	  static getDefault(): ResponsiveRuntime {
199	    if (!ResponsiveRuntime._default) {
200	      ResponsiveRuntime._default = new ResponsiveRuntime();
201	    }
202	    return ResponsiveRuntime._default;
203	  }
204	
205	  static resetDefault(): void {
206	    ResponsiveRuntime._default?.dispose();
207	    ResponsiveRuntime._default = null;
208	  }
209	}
